<?php require_once __DIR__ . '/../includes/functions.php'; admin_require_login(); header('Content-Type: text/csv'); header('Content-Disposition: attachment; filename="scop-leads-'.date('Y-m-d').'.csv"'); $out=fopen('php://output','w'); fputcsv($out,['Date','Name','Mobile','Email','City','Pincode','10th %','12th %','Stream','Course','Scholarship','Status','Temperature','Source','Message']); $pdo=db(); if($pdo){ foreach($pdo->query('SELECT * FROM leads ORDER BY created_at DESC') as $l) fputcsv($out,[$l['created_at'],$l['student_name'],$l['mobile'],$l['email'],$l['city'],$l['pincode'],$l['percentage_10'],$l['percentage_12'],$l['stream'],$l['course_interested'],$l['scholarship'],$l['status'],$l['lead_temperature'],$l['source'],$l['message']]); } else { foreach(fallback_leads() as $l) fputcsv($out,[$l['created_at']??'',$l['student_name']??'',$l['mobile']??'',$l['email']??'',$l['city']??'',$l['pincode']??'',$l['percentage_10']??'',$l['percentage_12']??'',$l['stream']??'',$l['course_interested']??'',$l['scholarship']??'',$l['status']??'',$l['lead_temperature']??'',$l['source']??'',$l['message']??'']); } exit; ?>
